	@Test
	void everySimpleGraphThroughFiveNodesMatchesExhaustivePairsAndIndependentTrace() {
		for (int nodeCount = 0; nodeCount <= 5; nodeCount++) {
			List<SimpleEdge> possibleEdges = possibleEdges(nodeCount);
			int graphCount = 1 << possibleEdges.size();
			for (int edgeMask = 0; edgeMask < graphCount; edgeMask++) {
				List<SimpleEdge> edges = new ArrayList<>();
				for (int ordinal = 0; ordinal < possibleEdges.size(); ordinal++) {
					if ((edgeMask & 1 << ordinal) != 0) {
						edges.add(possibleEdges.get(ordinal));
					}
				}
				assertMatchesReference(nodeCount, edges,
						"nodes=" + nodeCount + ", edgeMask=" + Integer.toBinaryString(edgeMask));
			}
		}
	}

