	private static void assertAllocationBound(int nodeCount, List<SimpleEdge> edges, StopMode stopMode) {
		ThreadMXBean bean = allocationBean();
		boolean allocationMemoryWasEnabled = bean.isThreadAllocatedMemoryEnabled();
		try {
			if (!allocationMemoryWasEnabled) {
				bean.setThreadAllocatedMemoryEnabled(true);
			}
			assertTrue(bean.isThreadAllocatedMemoryEnabled(),
					"per-thread allocated-byte measurements must be enabled");
			long threadId = Thread.currentThread().threadId();
			assertEscapedAllocationIsMeasured(bean, threadId);
			GraphFixture fixture = fixture(nodeCount, edges);
			AllocationReceiver receiver = new AllocationReceiver(stopMode);
			long[] samples = new long[7];
			for (int warmup = 0; warmup < 20; warmup++) {
				receiver.reset();
				PackedDphypEnumerator.enumerate(fixture.graph, receiver);
			}
			for (int sample = 0; sample < samples.length; sample++) {
				receiver.reset();
				long before = bean.getThreadAllocatedBytes(threadId);
				boolean stopped = PackedDphypEnumerator.enumerate(fixture.graph, receiver);
				long after = bean.getThreadAllocatedBytes(threadId);
				assertTrue(before >= 0,
						"before enumeration sample " + sample + " must have a valid allocation reading");
				assertTrue(after >= 0, "after enumeration sample " + sample + " must have a valid allocation reading");
				samples[sample] = after - before;
				assertTrue(samples[sample] >= 0, "allocated-byte delta must not be negative");
				assertEquals(stopMode == StopMode.FIRST_SINGLETON ? 1 : 2, receiver.singletons,
						"the first actual pair follows the two endpoint singleton callbacks");
				assertEquals(stopMode == StopMode.FIRST_PAIR ? 1 : 0, receiver.pairs);
				assertEquals(stopMode != StopMode.FULL, stopped);
			}
			long minimum = Arrays.stream(samples).min().orElseThrow();
			long budget = 512L * (nodeCount + edges.size() + 1L);
			/*
			 * For certified ordinary graphs whose singleton-edge incidence rows are strictly ordered by opposite
			 * endpoint ordinal, the cold path checks and builds the exact CSR view in O(n + m) time and storage. The
			 * graph-size budget covers that certificate, offsets, incidences, and fixed object/array headers; refusal
			 * at the first singleton stops before the index is built. Uncertified ordinary graphs and hypergraphs
			 * retain the original indexes and are outside this allocation bound.
			 */
			System.out.printf("allocation graph nodes=%d edges=%d mode=%s minimumBytes=%d budgetBytes=%d samples=%s%n",
					nodeCount, edges.size(), stopMode, minimum, budget, Arrays.toString(samples));
			assertTrue(minimum <= budget,
					"minimum of seven warmed per-thread samples " + Arrays.toString(samples) + " bytes exceeds "
							+ budget + " byte graph-size bound for " + nodeCount + " nodes and " + edges.size()
							+ " edges");
		} finally {
			allocationControl = null;
			if (!allocationMemoryWasEnabled && bean.isThreadAllocatedMemoryEnabled()) {
				bean.setThreadAllocatedMemoryEnabled(false);
			}
		}
	}

	private static ThreadMXBean allocationBean() {
		var platformBean = ManagementFactory.getThreadMXBean();
		assertTrue(platformBean instanceof ThreadMXBean,
				"the runtime must expose the per-thread allocation counter for this regression test");
		ThreadMXBean bean = (ThreadMXBean) platformBean;
		assertTrue(bean.isThreadAllocatedMemorySupported(),
				"the runtime must support per-thread allocated-byte measurements; a missing counter is not a green skip");
		return bean;
	}

	private static void assertEscapedAllocationIsMeasured(ThreadMXBean bean, long threadId) {
		long before = allocatedBytes(bean, threadId, "before escaped allocation control");
		allocationControl = new byte[1024];
		long after = allocatedBytes(bean, threadId, "after escaped allocation control");
		long measuredBytes = after - before;
		assertTrue(measuredBytes >= 1024,
				"the per-thread allocation counter must observe an escaped 1024-byte control allocation; observed "
						+ measuredBytes + " bytes");
		allocationControl = null;
	}

	private static long allocatedBytes(ThreadMXBean bean, long threadId, String context) {
		long allocatedBytes = bean.getThreadAllocatedBytes(threadId);
		assertTrue(allocatedBytes >= 0, context + " must return a nonnegative allocation-counter reading");
		return allocatedBytes;
	}

